mapper.select:
SELECT * FROM ai_execution_task
WHERE project_id = #{projectId}
  AND create_user = #{createUser}
  AND idempotency_key = #{idempotencyKey}
LIMIT 1

SELECT * FROM ai_execution_step
WHERE task_id = #{taskId}
ORDER BY execution_case_id ASC, pos ASC

SELECT * FROM ai_execution_healing
WHERE task_id = #{taskId}
ORDER BY execution_step_id ASC, attempt ASC

SELECT * FROM ai_execution_artifact
WHERE status = 'AVAILABLE'
  AND retention_until IS NOT NULL
  AND retention_until <= #{now}
ORDER BY retention_until ASC
LIMIT #{limit}

SELECT * FROM ai_runner_lease
WHERE status = 'ACTIVE' AND expire_time < #{now}
ORDER BY expire_time ASC
LIMIT #{limit}

SELECT * FROM ai_execution_task WHERE project_id = #{projectId} AND status = 'QUEUED' AND execution_mode = 'AGENT' AND dispatch_mode = 'PULL' AND attempt_count < max_attempts AND (timeout_at IS NULL OR timeout_at > UNIX_TIMESTAMP(CURRENT_TIMESTAMP(3)) * 1000)
AND agent_type = #{agentType}
ORDER BY create_time ASC, id ASC LIMIT #{limit} FOR UPDATE SKIP LOCKED

mapper.sql:
WHERE project_id = #{projectId}

    AND (LOWER(name) LIKE CONCAT('%', #{likeKeyword}, '%') ESCAPE '!'
         OR LOWER(objective) LIKE CONCAT('%', #{likeKeyword}, '%') ESCAPE '!'
         OR id = #{keyword})

AND status = #{status}
AND verdict = #{verdict}
AND execution_mode = #{executionMode}

mapper.select:
SELECT * FROM ai_execution_task 
ORDER BY create_time DESC, id DESC
LIMIT #{offset}, #{limit}

SELECT ec.*, fc.num AS case_num, fc.name AS case_name FROM ai_execution_case ec LEFT JOIN functional_case fc ON fc.id = ec.case_id WHERE ec.task_id = #{taskId}
AND ec.status IN
#{status}
ORDER BY ec.pos ASC, ec.create_time ASC

SELECT * FROM ai_execution_event
WHERE task_id = #{taskId}
  AND sequence > #{cursor}
ORDER BY sequence ASC
LIMIT #{limit}

mapper.insert:
INSERT INTO ai_execution_healing (
    id, task_id, execution_case_id, execution_step_id, attempt, failure_type, original_locator,
    candidate_locators, selected_locator, reason, confidence, result, before_artifact_id,
    after_artifact_id, duration_ms, create_time, create_user
) VALUES (
    #{id}, #{taskId}, #{executionCaseId}, #{executionStepId}, #{attempt}, #{failureType}, #{originalLocator},
    #{candidateLocators}, #{selectedLocator}, #{reason}, #{confidence}, #{result}, #{beforeArtifactId},
    #{afterArtifactId}, #{durationMs}, #{createTime}, #{createUser}
)

INSERT INTO ai_runner (
    id, organization_id, name, runner_version, contract_version, status, operating_system,
    browser_capabilities, environment_labels, auth_token_hash, max_concurrency, active_count, last_heartbeat_time,
    create_time, update_time, create_user, update_user
) VALUES (
    #{id}, #{organizationId}, #{name}, #{runnerVersion}, #{contractVersion}, #{status}, #{operatingSystem},
    #{browserCapabilities}, #{environmentLabels}, #{authTokenHash}, #{maxConcurrency}, #{activeCount}, #{lastHeartbeatTime},
    #{createTime}, #{updateTime}, #{createUser}, #{updateUser}
)

INSERT INTO ai_execution_artifact (
    id, task_id, execution_case_id, case_id, step_id, purpose, file_id, file_name,
    storage_folder, content_type, size_bytes, sha256, redacted, status, retention_until,
    create_time, create_user
) VALUES (
    #{id}, #{taskId}, #{executionCaseId}, #{caseId}, #{stepId}, #{purpose}, #{fileId}, #{fileName},
    #{storageFolder}, #{contentType}, #{sizeBytes}, #{sha256}, #{redacted}, #{status}, #{retentionUntil},
    #{createTime}, #{createUser}
)

mapper.update:
UPDATE ai_execution_artifact
SET status = #{status}
WHERE id = #{id} AND status = 'AVAILABLE'

UPDATE ai_runner
SET status = #{status}, active_count = #{activeCount}, last_heartbeat_time = #{heartbeatTime},
    update_time = #{heartbeatTime}
WHERE id = #{id}

UPDATE ai_execution_task
SET runner_id = #{runnerId}, runner_lease_id = #{leaseId}, status = #{toStatus},
    attempt_count = attempt_count + 1, verdict = NULL, verdict_reason = NULL,
    version = version + 1, update_time = #{updateTime}
WHERE id = #{taskId} AND status = #{fromStatus} AND version = #{version}
  AND attempt_count < max_attempts

