INSERT INTO ai_execution_event (
    id, contract_version, runner_event_id, task_id, case_id, step_id, attempt, sequence, event_time, level, event_type, message,
    artifact_ids, sanitized_metadata, create_user
) VALUES (
    #{id}, COALESCE(#{contractVersion}, 'v1'), #{eventId}, #{taskId}, #{caseId}, #{stepId}, COALESCE(#{attempt}, 0),
    #{sequence}, #{eventTime}, #{level}, #{eventType}, #{message},
    #{artifactIdsJson}, #{sanitizedMetadata}, #{createUser}
)

mapper.update:
UPDATE ai_execution_task
SET status = #{status},
    version = version + 1,
    update_user = #{updateUser},
    update_time = #{updateTime}
WHERE id = #{id}

UPDATE ai_execution_task
SET status = #{status},
    confirm_required = 0,
    version = version + 1,
    update_user = #{updateUser},
    update_time = #{updateTime}
WHERE id = #{id}
  AND status = #{fromStatus}
  AND version = #{version}

UPDATE ai_execution_case
SET status = #{status},
    result = #{result},
    error_message = #{errorMessage},
    update_time = #{updateTime}
WHERE task_id = #{taskId}
  AND case_id = #{caseId}

